// Demo data: a year of GZCLP 4-day sessions, generated by running the real engine and
// "performing" each planned session with some misses. Used when no HEVY_API_KEY is set.

import type { HevyExercise, HevyWorkout } from "./hevy";
import { LIFTS } from "./lifts";
import { applyWorkout, initialState, planDay, type ProgramConfig } from "./program";
import { buildProgram, defaultConfig } from "./programs";
import { addDays, weekStart } from "./stats";
import { roundTo, toKg } from "./units";

function rng(seed: number) {
  return () => ((seed = (seed * 1664525 + 1013904223) >>> 0) / 4294967296);
}

const tid = (lift: string) => `demo-${lift}`;
const ex = (lift: string, sets: HevyExercise["sets"]): HevyExercise => ({ title: LIFTS[lift].hevy[0], exercise_template_id: tid(lift), sets });

export function demoData(today: string): { workouts: HevyWorkout[]; config: ProgramConfig } {
  const r = rng(11);
  const start = addDays(weekStart(today), -7 * 51);
  const cfg = defaultConfig("gzclp", "lb", start + "T00:00:00Z");
  for (const k of Object.keys(cfg.startWeights)) cfg.startWeights[k] = roundTo(cfg.startWeights[k] * 0.72, 5);
  const def = buildProgram(cfg)!;
  let state = initialState(def, cfg);
  const workouts: HevyWorkout[] = [];
  const offWeeks = new Set([17, 18, 33]);

  for (let d = start; d <= today; d = addDays(d, 1)) {
    const wk = Math.floor((Date.parse(d) - Date.parse(start)) / (7 * 864e5));
    const dow = (new Date(d + "T12:00:00Z").getUTCDay() + 6) % 7; // 0 = Mon
    const planned = [0, 1, 3, 4].includes(dow);
    const go = offWeeks.has(wk) ? r() < 0.1 : planned ? r() < 0.88 : r() < 0.05;
    if (!go) continue;

    const startH = 6 + Math.floor(r() * 2);
    const t0 = new Date(`${d}T${String(startH + 4).padStart(2, "0")}:${String(Math.floor(r() * 50)).padStart(2, "0")}:00Z`);
    if (!planned && r() < 0.6) {
      // occasional off-program accessory day
      const w: HevyWorkout = {
        id: `demo-${d}-x`, title: "Arms + conditioning", start_time: t0.toISOString(), end_time: new Date(+t0 + 40 * 6e4).toISOString(),
        exercises: [ex("bicepCurl", [1, 2, 3].map(() => ({ type: "normal", weight_kg: toKg(25, "lb"), reps: 12 }))), ex("chinUp", [1, 2, 3].map(() => ({ type: "normal", weight_kg: 0, reps: 8 })))],
      };
      workouts.push(w);
      continue;
    }

    const plan = planDay(def, cfg, state);
    const exercises: HevyExercise[] = plan.exercises.map((p) => {
      const sets: HevyExercise["sets"] = [];
      const kgOf = (lb: number) => Math.round(toKg(lb, "lb") * 100) / 100;
      if (p.scheme.includes("RM TEST")) {
        const top = state.slots[p.slotId].weight * 1.12;
        for (const f of [0.5, 0.7, 0.85, 0.95, 1]) sets.push({ type: "normal", weight_kg: kgOf(roundTo(top * f, 5)), reps: 5 });
        return ex(p.lift, sets);
      }
      if (p.tier === "T1") for (const f of [0.5, 0.75]) sets.push({ type: "warmup", weight_kg: kgOf(roundTo(p.sets[0].weight * f, 5)), reps: 3 });
      const missP = p.tier === "T1" ? 0.13 : p.tier === "T2" ? 0.1 : 0;
      const miss = r() < missP;
      p.sets.forEach((s, k) => {
        let reps = s.reps;
        if (miss && k >= p.sets.length - 2) reps = Math.max(1, s.reps - 1 - Math.floor(r() * 2));
        else if (s.amrap) reps = p.tier === "T3" ? 18 + Math.floor(r() * 10) : s.reps + Math.floor(r() * 5);
        sets.push({ type: "normal", weight_kg: kgOf(s.weight), reps, rpe: s.amrap ? 9 : null });
      });
      return ex(p.lift, sets);
    });
    const w: HevyWorkout = {
      id: `demo-${d}`, title: `GZCLP · ${plan.dayId}`, routine_id: null,
      start_time: t0.toISOString(), end_time: new Date(+t0 + (55 + Math.floor(r() * 30)) * 6e4).toISOString(), exercises,
    };
    state = applyWorkout(def, cfg, state, w, state.dayIndex);
    workouts.push(w);
  }
  return { workouts, config: { ...cfg, liftMap: Object.fromEntries(Object.keys(LIFTS).map((k) => [k, tid(k)])) } };
}
